    for (var gl = 0; gl < 3; gl++) {
      var gx = ((t * (30 + gl * 8) + hash(gl + 20) * 900) % (W + 200)) - 100, gy = 70 + gl * 26 + Math.sin(t * 1.3 + gl) * 8, fl = Math.sin(t * 7 + gl) * 4;
      ctx.beginPath(); ctx.moveTo(gx - 10, gy - fl); ctx.quadraticCurveTo(gx - 4, gy - 4, gx, gy); ctx.quadraticCurveTo(gx + 4, gy - 4, gx + 10, gy - fl); ctx.stroke();
    }
