    sea.addColorStop(0, '#1C78B2'); sea.addColorStop(0.55, '#26A6CC'); sea.addColorStop(1, '#6FDCDC');
    ctx.fillStyle = sea; ctx.fillRect(0, horizon, W, GROUND - horizon);
