    for (var wv = 0; wv < 5; wv++) {
      var wy = horizon + 30 + wv * 22, wo = (dist * 0.15 + t * 20 + wv * 70) % 140;
      ctx.beginPath();
      for (var xx = -wo; xx < W + 140; xx += 140) { ctx.moveTo(xx, wy); ctx.quadraticCurveTo(xx + 20, wy - 4, xx + 40, wy); }
      ctx.stroke();
    }
