      [[[-14, -10], [-4, -2], [-8, 10]], [[6, -14], [10, -2], [18, 4]], [[-2, 6], [8, 12]]].forEach(function (c) { ctx.beginPath(); ctx.moveTo(c[0][0], c[0][1]); for (var q = 1; q < c.length; q++) ctx.lineTo(c[q][0], c[q][1]); ctx.stroke(); });
